            return (moves, "two", vol1)

        state = (vol1, vol2)
        if state in visited:
            # Shouldn't happen due to gcd check, but guard against infinite loops
            raise ValueError("No solution found with the given parameters and start bucket.")
        visited.add(state)

        # Set source and destination according to starting bucket
        if source_is_one:
            src = vol1
            dst = vol2
            src_cap = bucket_one
            dst_cap = bucket_two
        else:
            src = vol2
            dst = vol1
            src_cap = bucket_two
            dst_cap = bucket_one

