        if src == 0:
            # Fill the source (starting) bucket
            src = src_cap
            moves += 1
        elif dst == dst_cap:
            # Empty the destination bucket
            dst = 0
            moves += 1
        else:
            # Pour from source to destination until source empty or destination full
            pour = min(src, dst_cap - dst)
            new_src = src - pour
            new_dst = dst + pour
            # Avoid arriving at the forbidden state: starting bucket empty and other full
            # If this pour would create that state, perform an alternative allowed action:
